#[allow(dead_code)]
const RAX: u8 = 0;
#[allow(dead_code)]
const RCX: u8 = 1;
#[allow(dead_code)]
const RDX: u8 = 2;
#[allow(dead_code)]
const RBX: u8 = 3;
#[allow(dead_code)]
const RSP: u8 = 4;
#[allow(dead_code)]
const RBP: u8 = 5;
#[allow(dead_code)]
const RSI: u8 = 6;
#[allow(dead_code)]
const RDI: u8 = 7;
#[allow(dead_code)]
const R8: u8 = 8;
#[allow(dead_code)]
const R9: u8 = 9;
#[allow(dead_code)]
const R10: u8 = 10;
#[allow(dead_code)]
const R11: u8 = 11;
#[allow(dead_code)]
const R12: u8 = 12;
#[allow(dead_code)]
const R13: u8 = 13;
#[allow(dead_code)]
const R14: u8 = 14;
#[allow(dead_code)]
const R15: u8 = 15;

// Argument registers per platform
#[cfg(target_os = "windows")]
const ARG_REGS: [u8; 4] = [RCX, RDX, R8, R9];

#[cfg(not(target_os = "windows"))]
const ARG_REGS: [u8; 6] = [RDI, RSI, RDX, RCX, R8, R9];

/// Native-stack probe stride used by the x64 JIT prologue.
///
/// Windows grows a thread stack one guard page at a time, and Unix kernels use
/// the same page granularity for stack expansion / guard detection. A JIT frame
/// that subtracts more than one page from RSP without probing can skip over the
/// guard page; deep compiled recursion then faults later in arbitrary helper or
/// shadow-stack code. Probe one page at a time before the subtract, then keep a
/// one-page headroom probe below the final RSP.
const STACK_BANG_PAGE_SIZE: i32 = 4096;

/// Keep code size bounded for malformed or extreme bytecode. A method needing a
/// frame larger than this falls back to the interpreter instead of emitting a
/// giant inline probe sequence.
const MAX_STACK_BANG_PROBES: usize = 512;

fn jit_stack_bang_enabled() -> bool {
    static CACHE: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *CACHE.get_or_init(|| {
        if cratonvm_types::flags::runtime_var_os("CRATONVM_JIT_NO_STACK_BANG").is_some() {
            return false;
        }
        match cratonvm_types::flags::runtime_var("CRATONVM_JIT_STACK_BANG") {
            Ok(v) => !matches!(
                v.trim().to_ascii_lowercase().as_str(),
                "0" | "false" | "off" | "no"
            ),
            Err(_) => true,
        }
    })
}

/// RSP-relative displacements to probe before `sub rsp, frame_size`.
///
/// Returned values are negative displacements from the pre-subtract RSP. They
/// cover every page crossed by the frame allocation and include the exact final
/// frame bottom when it is not page-aligned.
fn stack_bang_frame_probe_disps(frame_size: i32) -> Option<Vec<i32>> {
    if frame_size <= 0 {
        return Some(Vec::new());
    }
    let mut disps = Vec::new();
    let mut off = STACK_BANG_PAGE_SIZE;
    while off <= frame_size {
        if disps.len() >= MAX_STACK_BANG_PROBES {
            return None;
        }
        disps.push(-off);
        off = off.saturating_add(STACK_BANG_PAGE_SIZE);
        if off <= 0 {
            return None;
        }
    }
    if frame_size % STACK_BANG_PAGE_SIZE != 0 {
        if disps.len() >= MAX_STACK_BANG_PROBES {
            return None;
        }
        disps.push(-frame_size);
    }
    Some(disps)
}

// ---------------------------------------------------------------------------
// AVX2 runtime detection via CPUID
// ---------------------------------------------------------------------------

use std::sync::atomic::{AtomicU8, Ordering};

/// Cached AVX2 support: 0 = unknown, 1 = supported, 2 = not supported
static AVX2_SUPPORT: AtomicU8 = AtomicU8::new(0);

/// Cached SSE4.1 support: 0 = unknown, 1 = supported, 2 = not supported
static SSE41_SUPPORT: AtomicU8 = AtomicU8::new(0);

/// Check if the CPU supports AVX2 instructions (CPUID leaf 7, EBX bit 5).
/// Result is cached after first call.
pub fn has_avx2() -> bool {
    let cached = AVX2_SUPPORT.load(Ordering::Relaxed);
    if cached != 0 {
        return cached == 1;
    }
    let result = detect_avx2();
    AVX2_SUPPORT.store(if result { 1 } else { 2 }, Ordering::Relaxed);
    result
}

#[cfg(target_arch = "x86_64")]
fn detect_avx2() -> bool {
    // Check CPUID leaf 7, subleaf 0, EBX bit 5 = AVX2
    // Also verify OS supports AVX via XGETBV (CPUID leaf 1, ECX bit 27 = OSXSAVE)
    // SAFETY: __cpuid and __cpuid_count read CPU feature flags via the CPUID instruction
    // and _xgetbv reads the extended control register. These are read-only x86_64 intrinsics
    // with no memory side-effects; the target_arch gate above ensures we are on x86_64.
    unsafe {
        // Check OSXSAVE (leaf 1, ECX bit 27)
        let leaf1: std::arch::x86_64::CpuidResult = std::arch::x86_64::__cpuid(1);
        if leaf1.ecx & (1 << 27) == 0 {
            return false; // OS doesn't support XSAVE
        }
        // Check XCR0 bits 1-2 (SSE + AVX state saving)
        let xcr0: u64 = std::arch::x86_64::_xgetbv(0);
        if xcr0 & 0x06 != 0x06 {
            return false; // OS doesn't save AVX state
        }
        // Check AVX2 (leaf 7, EBX bit 5)
        let leaf7: std::arch::x86_64::CpuidResult = std::arch::x86_64::__cpuid_count(7, 0);
        leaf7.ebx & (1 << 5) != 0
    }
}

#[cfg(not(target_arch = "x86_64"))]
fn detect_avx2() -> bool {
    false
}

/// Check if the CPU supports SSE4.1 instructions (CPUID leaf 1, ECX bit 19).
/// Required for ROUNDSD/ROUNDSS (Math.floor/ceil/rint intrinsics).
pub fn has_sse41() -> bool {
    let cached = SSE41_SUPPORT.load(Ordering::Relaxed);
    if cached != 0 {
        return cached == 1;
    }
    let result = detect_sse41();
    SSE41_SUPPORT.store(if result { 1 } else { 2 }, Ordering::Relaxed);
    result
}

#[cfg(target_arch = "x86_64")]
fn detect_sse41() -> bool {
    // SAFETY: __cpuid is a read-only x86_64 intrinsic that queries CPU feature flags
    // via the CPUID instruction. The target_arch gate ensures we are on x86_64.
    // The `unsafe` block is tolerated-but-not-required in newer rustc; keep it so
    // older toolchains remain supported.
    #[allow(unused_unsafe)]
    unsafe {
        let leaf1: std::arch::x86_64::CpuidResult = std::arch::x86_64::__cpuid(1);
        leaf1.ecx & (1 << 19) != 0
    }
}

#[cfg(not(target_arch = "x86_64"))]
fn detect_sse41() -> bool {
    false
}

/// Cached feature support for the JIT-intrinsic families: 0 = unknown,
/// 1 = supported, 2 = not supported. One slot per feature.
static POPCNT_SUPPORT: AtomicU8 = AtomicU8::new(0);
static SSE42_SUPPORT: AtomicU8 = AtomicU8::new(0);
static LZCNT_SUPPORT: AtomicU8 = AtomicU8::new(0);
static BMI1_SUPPORT: AtomicU8 = AtomicU8::new(0);
static PCLMUL_SUPPORT: AtomicU8 = AtomicU8::new(0);

#[cfg(target_arch = "x86_64")]
fn cpuid_bit(leaf: u32, sub: u32, reg: u8, bit: u32) -> bool {
    // SAFETY: __cpuid_count is a read-only x86_64 intrinsic querying CPU
    // feature flags via CPUID. The target_arch gate ensures x86_64.
    #[allow(unused_unsafe)]
    unsafe {
        let r = std::arch::x86_64::__cpuid_count(leaf, sub);
        let v = match reg {
            0 => r.eax,
            1 => r.ebx,
            2 => r.ecx,
            _ => r.edx,
        };
        v & (1 << bit) != 0
    }
}

#[cfg(not(target_arch = "x86_64"))]
fn cpuid_bit(_leaf: u32, _sub: u32, _reg: u8, _bit: u32) -> bool {
    false
}

fn cached_feature(slot: &AtomicU8, detect: impl FnOnce() -> bool) -> bool {
    let cached = slot.load(Ordering::Relaxed);
    if cached != 0 {
        return cached == 1;
    }
    let result = detect();
    slot.store(if result { 1 } else { 2 }, Ordering::Relaxed);
    result
}

/// CPU supports the `POPCNT` instruction (CPUID leaf 1, ECX bit 23).
/// Required for `Integer/Long.bitCount` intrinsics.
pub fn has_popcnt() -> bool {
    cached_feature(&POPCNT_SUPPORT, || cpuid_bit(1, 0, 2, 23))
}

/// CPU supports SSE4.2 — implies the `CRC32` instruction (CPUID leaf 1,
/// ECX bit 20). Required for `CRC32C` intrinsics.
pub fn has_sse42() -> bool {
    cached_feature(&SSE42_SUPPORT, || cpuid_bit(1, 0, 2, 20))
}

/// CPU supports `LZCNT` (AMD ABM / Intel since Haswell — CPUID leaf
/// 0x8000_0001, ECX bit 5). Required for branchless
/// `numberOfLeadingZeros`. Without it, fall back to `BSR` + fixups.
pub fn has_lzcnt() -> bool {
    cached_feature(&LZCNT_SUPPORT, || cpuid_bit(0x8000_0001, 0, 2, 5))
}

/// CPU supports BMI1 — implies the `TZCNT` instruction (CPUID leaf 7,
/// subleaf 0, EBX bit 3). Required for branchless
/// `numberOfTrailingZeros`. Without it, fall back to `BSF` + fixups.
pub fn has_bmi1() -> bool {
    cached_feature(&BMI1_SUPPORT, || cpuid_bit(7, 0, 1, 3))
}

/// CPU supports `PCLMULQDQ` carry-less multiply (CPUID leaf 1, ECX bit 1).
/// Required for a folding `CRC32` (IEEE polynomial) implementation.
pub fn has_pclmulqdq() -> bool {
    cached_feature(&PCLMUL_SUPPORT, || cpuid_bit(1, 0, 2, 1))
}

// ---------------------------------------------------------------------------
// SIMD loop analysis and vectorization
// ---------------------------------------------------------------------------

/// Information about a vectorizable int-array sum reduction loop.
/// Pattern: for (i = start; i < bound; i++) sum += arr[i]
#[derive(Debug)]
#[allow(dead_code)]
struct SimdIntArraySum {
    /// Bytecode PC of the loop header
    header_pc: usize,
    /// Bytecode PC of the back-edge instruction
    back_edge_pc: usize,
    /// Local index of the induction variable (i)
    iv_local: usize,
    /// Local index of the accumulator (sum)
    acc_local: usize,
    /// Local index of the array reference
    array_local: usize,
    /// Local index of the loop bound
    bound_local: usize,
    /// Whether accumulator is long (i2l + ladd + lstore vs iadd + istore)
    acc_is_long: bool,
}

/// Detect a vectorizable int-array-sum pattern in a loop body.
/// Matches: iload_sum, aload_arr, iload_iv, iaload, iadd, istore_sum, iinc iv 1, goto
/// Or with long accumulator: aload_arr, iload_iv, iaload, i2l, lload_sum, ladd, lstore_sum
fn detect_int_array_sum(
    code: &[u8],
    header: usize,
    back_edge: usize,
    iv_local: usize,
) -> Option<SimdIntArraySum> {
    // back_edge should be a goto instruction
    if code.get(back_edge).copied() != Some(0xa7) {
        return None;
    }
    let back_edge_end = back_edge + 3;

    // The loop header should start with: iload_iv, iload_bound, if_icmpge exit
    let mut pc = header;

    // Match: iload <iv>
    let iv_check = extract_iload_local(code, pc)?;
    if iv_check != iv_local {
        return None;
    }
    pc += if code[pc] == 0x15 { 2 } else { 1 };

    // Match: iload <bound>
    let bound_local = extract_iload_local(code, pc)?;
    pc += if code[pc] == 0x15 { 2 } else { 1 };

    // Match: if_icmpge <exit>
    if pc + 2 >= back_edge_end {
        return None;
    }
    if code[pc] != 0xa2 {
        return None;
    }
    pc += 3; // skip if_icmpge + offset

    // Now match loop body: aload arr, iload iv, iaload, (optional i2l), load sum, add, store sum
    // Pattern A (int sum): aload_arr, iload_iv, iaload, iload_sum, iadd (reversed), istore_sum
    // Pattern B: iload_sum, aload_arr, iload_iv, iaload, iadd, istore_sum

    // Try: aload arr, iload iv, iaload
    let array_local = extract_aload_local(code, pc)?;
    pc += if code[pc] == 0x19 { 2 } else { 1 };

    let iv_load2 = extract_iload_local(code, pc)?;
    if iv_load2 != iv_local {
        return None;
    }
    pc += if code[pc] == 0x15 { 2 } else { 1 };

    // iaload (0x2e)
    if pc >= back_edge_end || code[pc] != 0x2e {
        return None;
    }
    pc += 1;

    // Check for i2l conversion (long accumulator)
    let acc_is_long = pc < back_edge_end && code[pc] == 0x85;
    if acc_is_long {
        pc += 1;
    }

    let acc_local;
    if acc_is_long {
        // Long path: lload sum, ladd, lstore sum
        acc_local = extract_lload_local(code, pc)?;
        pc += if code[pc] == 0x16 { 2 } else { 1 };

        // ladd (0x61)
        if pc >= back_edge_end || code[pc] != 0x61 {
            return None;
        }
        pc += 1;

        // lstore sum
        let store_local = extract_lstore_local(code, pc)?;
        if store_local != acc_local {
            return None;
        }
        pc += if code[pc] == 0x37 { 2 } else { 1 };
    } else {
        // Int path: for simplicity, only support long accumulator (most common for benchmarks)
        return None;
    }

    // Should be followed by iinc iv, 1 and then goto header
    if pc + 2 >= back_edge_end {
        return None;
    }
    if code[pc] != 0x84 {
        return None;
    }
    // Widening: u8 -> wider int (bytecode operand byte, value fits)
    if code[pc + 1] as usize != iv_local {
        // Widening: always safe
        return None;
    }
    if code[pc + 2] != 0x01 {
        return None;
    }
    // pc + 3 should be the back_edge (goto)
    if pc + 3 != back_edge {
        return None;
    }

    Some(SimdIntArraySum {
        header_pc: header,
        back_edge_pc: back_edge,
        iv_local,
        acc_local,
        array_local,
        bound_local,
        acc_is_long,
    })
}

/// Extract local index from an lload instruction at pc.
fn extract_lload_local(code: &[u8], pc: usize) -> Option<usize> {
    match *code.get(pc)? {
        0x1e => Some(0), // lload_0
        0x1f => Some(1), // lload_1
        0x20 => Some(2), // lload_2
        0x21 => Some(3), // lload_3
        // Cast: non-negative index/count to usize
        0x16 => code.get(pc + 1).map(|&b| b as usize), // lload
        _ => None,
    }
}

/// Extract local index from an lstore instruction at pc.
fn extract_lstore_local(code: &[u8], pc: usize) -> Option<usize> {
    match *code.get(pc)? {
        0x3f => Some(0), // lstore_0
        0x40 => Some(1), // lstore_1
        0x41 => Some(2), // lstore_2
        0x42 => Some(3), // lstore_3
        // Cast: non-negative index/count to usize
        0x37 => code.get(pc + 1).map(|&b| b as usize), // lstore
        _ => None,
    }
}

/// Extract local index from a dload instruction at pc.
fn extract_dload_local(code: &[u8], pc: usize) -> Option<usize> {
    match *code.get(pc)? {
        0x26 => Some(0), // dload_0
        0x27 => Some(1), // dload_1
        0x28 => Some(2), // dload_2
        0x29 => Some(3), // dload_3
        // Cast: non-negative index/count to usize
        0x18 => code.get(pc + 1).map(|&b| b as usize), // dload
        _ => None,
    }
}

/// Extract local index from a dstore instruction at pc.
fn extract_dstore_local(code: &[u8], pc: usize) -> Option<usize> {
    match *code.get(pc)? {
        0x47 => Some(0), // dstore_0
        0x48 => Some(1), // dstore_1
        0x49 => Some(2), // dstore_2
        0x4a => Some(3), // dstore_3
        // Cast: non-negative index/count to usize
        0x39 => code.get(pc + 1).map(|&b| b as usize), // dstore
        _ => None,
    }
}

/// Detect a vectorizable double-array-sum pattern in a loop body.
/// Matches: dload_sum, aload_arr, iload_iv, daload, dadd, dstore_sum, iinc iv 1, goto
/// Or:      aload_arr, iload_iv, daload, dload_sum, dadd, dstore_sum, iinc iv 1, goto
fn detect_fp_array_sum(
    code: &[u8],
    header: usize,
    back_edge: usize,
    iv_local: usize,
) -> Option<SimdFpArraySum> {
    // back_edge should be a goto instruction
    if code.get(back_edge).copied() != Some(0xa7) {
        return None;
    }
    let back_edge_end = back_edge + 3;

    // Header starts with: iload <iv>, iload <bound>, if_icmpge <exit>
    let mut pc = header;

    let iv_check = extract_iload_local(code, pc)?;
    if iv_check != iv_local {
        return None;
    }
    pc += if code[pc] == 0x15 { 2 } else { 1 };

    let bound_local = extract_iload_local(code, pc)?;
    pc += if code[pc] == 0x15 { 2 } else { 1 };

    if pc + 2 >= back_edge_end || code[pc] != 0xa2 {
        return None; // expect if_icmpge
    }
    pc += 3;

    // Now match loop body. Two patterns:
    // Pattern A: aload arr, iload iv, daload, dload sum, dadd, dstore sum
    // Pattern B: dload sum, aload arr, iload iv, daload, dadd, dstore sum

    let (array_local, acc_local);

    // Try pattern A: aload arr first
    if let Some(arr) = extract_aload_local(code, pc) {
        let arr_len = if code[pc] == 0x19 { 2 } else { 1 };
        let pc2 = pc + arr_len;

        let iv2 = extract_iload_local(code, pc2);
        if iv2 == Some(iv_local) {
            let iv2_len = if code[pc2] == 0x15 { 2 } else { 1 };
            let pc3 = pc2 + iv2_len;

            // daload (0x31)
            if pc3 < back_edge_end && code[pc3] == 0x31 {
                let pc4 = pc3 + 1;

                // dload sum
                if let Some(sum) = extract_dload_local(code, pc4) {
                    let sum_len = if code[pc4] == 0x18 { 2 } else { 1 };
                    let pc5 = pc4 + sum_len;

                    // dadd (0x63)
                    if pc5 < back_edge_end && code[pc5] == 0x63 {
                        let pc6 = pc5 + 1;

                        // dstore sum
                        if let Some(store_sum) = extract_dstore_local(code, pc6) {
                            if store_sum == sum {
                                let store_len = if code[pc6] == 0x39 { 2 } else { 1 };
                                let pc7 = pc6 + store_len;

                                // iinc iv 1
                                if pc7 + 2 < back_edge_end
                                    && code[pc7] == 0x84
                                    && code[pc7 + 1] as usize == iv_local // Widening: always safe
                                    && code[pc7 + 2] == 0x01
                                    && pc7 + 3 == back_edge
                                {
                                    return Some(SimdFpArraySum {
                                        header_pc: header,
                                        back_edge_pc: back_edge,
                                        iv_local,
                                        acc_local: sum,
                                        array_local: arr,
                                        bound_local,
                                        sse_op: 0x58, // ADDPD
                                    });
                                }
                            }
                        }
                    }
                }
            }
        }

        // If pattern A didn't match fully, fall through
        array_local = 0; // not used
        acc_local = 0;
    } else {
        array_local = 0;
        acc_local = 0;
    }

    // Try pattern B: dload sum first
    if let Some(sum) = extract_dload_local(code, pc) {
        let sum_len = if code[pc] == 0x18 { 2 } else { 1 };
        let pc2 = pc + sum_len;

        if let Some(arr) = extract_aload_local(code, pc2) {
            let arr_len = if code[pc2] == 0x19 { 2 } else { 1 };
            let pc3 = pc2 + arr_len;

            let iv2 = extract_iload_local(code, pc3);
            if iv2 == Some(iv_local) {
                let iv2_len = if code[pc3] == 0x15 { 2 } else { 1 };
                let pc4 = pc3 + iv2_len;

                // daload (0x31)
                if pc4 < back_edge_end && code[pc4] == 0x31 {
                    let pc5 = pc4 + 1;

                    // dadd (0x63)
                    if pc5 < back_edge_end && code[pc5] == 0x63 {
                        let pc6 = pc5 + 1;

                        // dstore sum
                        if let Some(store_sum) = extract_dstore_local(code, pc6) {
                            if store_sum == sum {
                                let store_len = if code[pc6] == 0x39 { 2 } else { 1 };
                                let pc7 = pc6 + store_len;

                                if pc7 + 2 < back_edge_end
                                    && code[pc7] == 0x84
                                    && code[pc7 + 1] as usize == iv_local // Widening: always safe
                                    && code[pc7 + 2] == 0x01
                                    && pc7 + 3 == back_edge
                                {
                                    return Some(SimdFpArraySum {
                                        header_pc: header,
                                        back_edge_pc: back_edge,
                                        iv_local,
                                        acc_local: sum,
                                        array_local: arr,
                                        bound_local,
                                        sse_op: 0x58, // ADDPD
                                    });
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    let _ = (array_local, acc_local); // suppress unused warnings
    None
}

// ---------------------------------------------------------------------------
// T5.2.15 — SuperWord / element-wise SIMD detection
// ---------------------------------------------------------------------------

/// Operation that joins the two source vectors in an element-wise loop.
///
/// Expressed as the bytecode opcode of the arithmetic that appears
/// between the two `iaload`s and the `iastore` — the JIT maps this to
/// `PADDD` / `PSUBD` / `PMULLD` when lowering.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[allow(dead_code)]
pub(crate) enum ElementWiseOp {
    /// iadd (0x60) → PADDD
    Add,
    /// isub (0x64) → PSUBD
    Sub,
    /// imul (0x68) → PMULLD (SSE4.1 or AVX2)
    Mul,
    /// iand (0x7E) → PAND
    And,
    /// ior  (0x80) → POR
    Or,
    /// ixor (0x82) → PXOR
    Xor,
}

/// Information about a vectorizable int-array element-wise loop.
///
/// Matches the pattern:
///
/// ```text
/// for (i = 0; i < n; i++) out[i] = a[i] OP b[i];
/// ```
///
/// where `OP` is one of `iadd`, `isub`, `imul`, `iand`, `ior`, `ixor`.
/// The detector also accepts the simpler form `a[i] OP b[i]` when the
/// result is stored back into `a` (in-place).
#[derive(Debug, Clone)]
#[allow(dead_code)]
pub(crate) struct SimdArrayElementWise {
    /// Bytecode PC of the loop header.
    pub header_pc: usize,
    /// Bytecode PC of the back-edge.
    pub back_edge_pc: usize,
    /// Local index of the induction variable.
    pub iv_local: usize,
    /// Local index of the destination array.
    pub out_local: usize,
    /// Local index of source array A.
    pub a_local: usize,
    /// Local index of source array B.
    pub b_local: usize,
    /// Local index of the loop bound (upper limit of `i`).
    pub bound_local: usize,
    /// Operation to perform element-wise.
    pub op: ElementWiseOp,
}

/// Try to detect an int-array element-wise pattern in a loop body.
///
/// The recognized shape is:
///
/// ```text
/// header: iload iv ; iload bound ; if_icmpge exit
/// body:   aload out ; iload iv ;
///         aload a ; iload iv ; iaload ;
///         aload b ; iload iv ; iaload ;
///         i{add,sub,mul,and,or,xor} ;
///         iastore ;
///         iinc iv 1 ;
///         goto header
/// ```
///
/// Returns `Some` on a match; `None` otherwise. The caller stores the
/// result on the `Compiler` for downstream SIMD emission.
#[allow(dead_code)]
pub(crate) fn detect_int_array_element_wise(
    code: &[u8],
    header: usize,
    back_edge: usize,
    iv_local: usize,
) -> Option<SimdArrayElementWise> {
    if back_edge >= code.len() || code[back_edge] != 0xa7 {
        return None;
    }
    let back_edge_end = back_edge + 3;
    let mut pc = header;

    // Header: iload iv ; iload bound ; if_icmpge exit
    let iv_check = extract_iload_local(code, pc)?;
    if iv_check != iv_local {
        return None;
    }
    pc += if code[pc] == 0x15 { 2 } else { 1 };

    let bound_local = extract_iload_local(code, pc)?;
    pc += if code[pc] == 0x15 { 2 } else { 1 };

    if pc + 2 >= back_edge_end || code[pc] != 0xa2 {
        return None;
    }
    pc += 3;

    // Body: aload out ; iload iv
    let out_local = extract_aload_local(code, pc)?;
    pc += if code[pc] == 0x19 { 2 } else { 1 };

    let iv2 = extract_iload_local(code, pc)?;
    if iv2 != iv_local {
        return None;
    }
    pc += if code[pc] == 0x15 { 2 } else { 1 };

    // aload a ; iload iv ; iaload
    let a_local = extract_aload_local(code, pc)?;
    pc += if code[pc] == 0x19 { 2 } else { 1 };
    let iv3 = extract_iload_local(code, pc)?;
    if iv3 != iv_local {
        return None;
    }
    pc += if code[pc] == 0x15 { 2 } else { 1 };
    if pc >= back_edge_end || code[pc] != 0x2e {
        return None; // iaload
    }
    pc += 1;

    // aload b ; iload iv ; iaload
    let b_local = extract_aload_local(code, pc)?;
    pc += if code[pc] == 0x19 { 2 } else { 1 };
    let iv4 = extract_iload_local(code, pc)?;
    if iv4 != iv_local {
        return None;
    }
    pc += if code[pc] == 0x15 { 2 } else { 1 };
    if pc >= back_edge_end || code[pc] != 0x2e {
        return None;
    }
    pc += 1;

    // Element-wise op
    let op = match code.get(pc).copied()? {
        0x60 => ElementWiseOp::Add,
        0x64 => ElementWiseOp::Sub,
        0x68 => ElementWiseOp::Mul,
        0x7E => ElementWiseOp::And,
        0x80 => ElementWiseOp::Or,
        0x82 => ElementWiseOp::Xor,
        _ => return None,
    };
    pc += 1;

    // iastore
    if pc >= back_edge_end || code[pc] != 0x4F {
        return None;
    }
    pc += 1;

    // iinc iv, 1 ; goto header
    if pc + 2 >= back_edge_end
        || code[pc] != 0x84
        // Widening: u8 -> wider int (bytecode operand byte, value fits)
        || code[pc + 1] as usize != iv_local
        || code[pc + 2] != 0x01
        || pc + 3 != back_edge
    {
        return None;
    }

    Some(SimdArrayElementWise {
        header_pc: header,
        back_edge_pc: back_edge,
        iv_local,
        out_local,
        a_local,
        b_local,
        bound_local,
        op,
    })
}

// ---------------------------------------------------------------------------
// T5.2.17 — Loop unswitching detection
// ---------------------------------------------------------------------------

/// Candidate for loop unswitching.
///
/// Describes a loop whose body contains a conditional branch on a
/// local that is never written inside the loop. The JIT can legally
/// duplicate the loop into two loops — one for each side of the
/// branch — and hoist the condition check out of the header.
///
/// Detection runs on loops of ≤ `MAX_UNSWITCH_BYTECODES` bytes to
/// bound the code-size blow-up from the duplication.
#[derive(Debug, Clone)]
#[allow(dead_code)]
pub(crate) struct LoopUnswitchCandidate {
    /// Bytecode PC of the loop header.
    pub header_pc: usize,
    /// Bytecode PC of the back-edge goto.
    pub back_edge_pc: usize,
    /// Bytecode PC of the invariant conditional branch inside the body.
    pub invariant_branch_pc: usize,
    /// Local variable index whose value is the branch predicate and
    /// that is never re-assigned in the loop body.
    pub invariant_local: usize,
    /// Opcode of the branch (if_icmp*, ifeq, ifne, etc.) so the
    /// emitter can mirror it when duplicating.
    pub branch_op: u8,
}

/// Upper limit on loop body size eligible for unswitching.
///
/// Chosen to match the unrolling budget: duplicating a 32-byte loop
/// doubles to 64 bytes, comparable to the 32-byte unroll limit in the
/// static heuristic. Larger loops have more total cost and less
/// marginal benefit from hoisting a single branch.
pub const MAX_UNSWITCH_BYTECODES: usize = 32;

/// Detect loops eligible for unswitching.
///
/// A loop is a candidate when:
/// 1. Its body size is ≤ `MAX_UNSWITCH_BYTECODES` bytes.
/// 2. The body contains an `ifeq/ifne/.../if_icmp*` instruction.
/// 3. The predicate comes from an `iload` whose local is never
///    written (no `istore`/`iinc`) anywhere in the loop body.
///
/// When multiple branches qualify, the first one is returned. Nested
/// loops are handled by the caller (the `loops` list already
/// enumerates each level independently).
#[allow(dead_code)]
pub(crate) fn detect_loop_unswitch_candidates(
    code: &[u8],
    code_len: usize,
    loops: &[(usize, usize)],
) -> Vec<LoopUnswitchCandidate> {
    let mut out = Vec::new();
    for &(header, back_edge) in loops {
        if header >= code_len || back_edge >= code_len {
            continue;
        }
        let body_size = back_edge.saturating_sub(header);
        if body_size == 0 || body_size > MAX_UNSWITCH_BYTECODES {
            continue;
        }

        // Collect locals written inside the loop (to exclude them
        // from the invariant set).
        let mut written: u64 = 0;
        {
            let mut pc = header;
            while pc <= back_edge && pc < code_len {
                match code[pc] {
                    // istore/lstore/fstore/dstore/astore <local>
                    0x36..=0x3A if pc + 1 < code_len => {
                        // Widening: u8 -> wider int (bytecode operand byte, value fits)
                        written |= 1u64 << (code[pc + 1] as usize & 0x3F);
                    }
                    // istore_0..istore_3
                    // Widening: u8 -> usize (opcode-relative local index, value fits)
                    0x3B..=0x3E => written |= 1u64 << ((code[pc] - 0x3B) as usize),
                    // lstore_0..lstore_3
                    // Widening: u8 -> usize (opcode-relative local index, value fits)
                    0x3F..=0x42 => written |= 1u64 << ((code[pc] - 0x3F) as usize),
                    // fstore_0..fstore_3
                    // Widening: u8 -> usize (opcode-relative local index, value fits)
                    0x43..=0x46 => written |= 1u64 << ((code[pc] - 0x43) as usize),
                    // dstore_0..dstore_3
                    // Widening: u8 -> usize (opcode-relative local index, value fits)
                    0x47..=0x4A => written |= 1u64 << ((code[pc] - 0x47) as usize),
                    // astore_0..astore_3
                    // Widening: u8 -> usize (opcode-relative local index, value fits)
                    0x4B..=0x4E => written |= 1u64 << ((code[pc] - 0x4B) as usize),
                    // iinc <local>, _
                    0x84 if pc + 1 < code_len => {
                        // Widening: u8 -> wider int (bytecode operand byte, value fits)
                        written |= 1u64 << (code[pc + 1] as usize & 0x3F);
                    }
                    _ => {}
                }
                pc += crate::scev::bytecode_len(code, pc, code_len);
            }
        }

        // Walk again looking for an `iload L; if*` pair where L is not
        // in `written`. The invariant_local must be < 64 so it fits in
        // the bitmask.
        let mut pc = header;
        while pc < back_edge && pc < code_len {
            // Try to extract an iload and its local.
            let (iload_local, iload_len) = match code.get(pc).copied() {
                // Widening: u8 -> usize (opcode-relative local index, value fits)
                Some(0x1A..=0x1D) => (Some((code[pc] - 0x1A) as usize), 1usize),
                // Widening: u8 -> wider int (bytecode operand byte, value fits)
                Some(0x15) if pc + 1 < code_len => (Some(code[pc + 1] as usize), 2usize),
                _ => (None, 0),
            };
            if let Some(local) = iload_local {
                let next_pc = pc + iload_len;
                if next_pc < code_len {
                    let op = code[next_pc];
                    // if_icmpeq..if_icmple need a second iload, so we
                    // match the simpler ifeq..ifle (0x99..=0x9E) that
                    // operate on the single top-of-stack.
                    let is_unary_branch = matches!(op, 0x99..=0x9E);
                    if is_unary_branch && local < 64 && (written & (1u64 << local)) == 0 {
                        out.push(LoopUnswitchCandidate {
                            header_pc: header,
                            back_edge_pc: back_edge,
                            invariant_branch_pc: next_pc,
                            invariant_local: local,
                            branch_op: op,
                        });
                        break; // one candidate per loop is enough
                    }
                }
            }
            pc += crate::scev::bytecode_len(code, pc, code_len);
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Bytecode compatibility check
// ---------------------------------------------------------------------------

/// Scan bytecode and determine JIT compatibility.
///
/// Returns `Some(needs_heap)` if the method can be JIT-compiled, `None` otherwise.
/// `needs_heap` is true if the method uses array/object opcodes that require
/// a heap pointer as a hidden first argument.
/// Kill-switch for the dup_x1/dup_x2 codegen arms (`CRATONVM_JIT_NO_DUPX=1`
/// restores the historical "bail to interpreter" behaviour). Added for
/// regression bisection while the arms are fresh.
fn dupx_codegen_disabled() -> bool {
    static CACHE: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *CACHE.get_or_init(|| cratonvm_types::flags::runtime_var_os("CRATONVM_JIT_NO_DUPX").is_some())
}

/// DBG bisection (spring-bug-11): disable ONLY the dup_x1 (0x5A) codegen arm,
/// to tell whether the Groovy SIGSEGV is in dup_x1 vs dup_x2 vs a co-located op.
fn dup_x1_codegen_disabled() -> bool {
    static CACHE: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *CACHE.get_or_init(|| cratonvm_types::flags::runtime_var_os("CRATONVM_JIT_NO_DUP_X1").is_some())
}

/// DBG bisection (spring-bug-11): disable ONLY the dup_x2 (0x5B) codegen arm.
fn dup_x2_codegen_disabled() -> bool {
    static CACHE: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *CACHE.get_or_init(|| cratonvm_types::flags::runtime_var_os("CRATONVM_JIT_NO_DUP_X2").is_some())
}

/// DBG bisection (spring-bug-11): immediately `canonicalize_stack()` after a
/// dup_x1/dup_x2 rotate, eliminating the non-canonical rotated frame offsets in
/// place. If this clears the crash, the defect is a downstream consumer of the
/// non-canonical offsets (canonicalize parallel-move / a merge that assumes
/// canonical layout); if it does NOT, the rotate model itself or a co-located
/// op is to blame.
fn dupx_eager_canon() -> bool {
    static CACHE: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *CACHE.get_or_init(|| {
        cratonvm_types::flags::runtime_var_os("CRATONVM_JIT_DUPX_EAGER_CANON").is_some()
    })
}

pub fn jit_scan(code: &[u8], code_len: usize, descriptor: &str) -> Option<JitScanResult> {
    let mut needs_heap = false;
    let mut multianewarray_ops = Vec::new();
    let mut field_ops = Vec::new();
    let mut typecheck_ops = Vec::new();
    let mut static_field_ops = Vec::new();
    let mut invoke_ops: Vec<(usize, u16, u8)> = Vec::new(); // (pc, cp_index, opcode)
    let mut new_ops: Vec<(usize, u16)> = Vec::new(); // (pc, cp_index) for `new` (0xbb)
    let mut anewarray_ops: Vec<(usize, u16)> = Vec::new(); // (pc, cp_index) for `anewarray` (0xbd)
    let mut ldc_ops: Vec<(usize, u16)> = Vec::new(); // (pc, cp_index) for `ldc`/`ldc_w`
    let mut ldc2w_ops: Vec<(usize, u16)> = Vec::new(); // (pc, cp_index) for `ldc2_w` (0x14)
    let mut indy_ops: Vec<(usize, u16)> = Vec::new(); // (pc, cp_index) for `invokedynamic` (0xba)
    let mut has_athrow = false; // RBC.6 — method contains 0xbf
    let mut has_newarray = false; // Primitive array allocation (0xbc)
                                  // RBC.6 local-handler-safety fix — every `*load`/`*store`/`iinc`
                                  // instruction's (bytecode_pc, local_slot). Populated inline in the
                                  // existing, already-correct per-opcode arms below (zero new pc-
                                  // advancement logic — just recording a side effect), so it can never
                                  // diverge from this scanner's own opcode-width decoding. Consumed by
                                  // `local_handler_reads_unsafe_local` (jit/src/lib.rs) to conservatively
                                  // verify every exception-table handler in a method only ever reads a
                                  // local it (or something reachable before it in bytecode order,
                                  // starting from the handler's own entry pc) has itself written — see
                                  // that function's doc comment for why this check exists.
    let mut local_slot_ops: Vec<(usize, bool, u16)> = Vec::new(); // (pc, is_store, slot)
                                                                  // BUG-LQB-SCOPE (RELAXED, see docs/feature-designs/jit-local-exception-handlers.md
                                                                  // — documented alongside the RBC.6 relaxation it was found while
                                                                  // validating): this scanner used to track the earliest "committing side
                                                                  // effect" pc and refuse to compile ANY method where one preceded an
                                                                  // `invokedynamic` in raw bytecode-pc order, because at the time
                                                                  // (`752796a0a`, 2026-07-07) the trap's fallback was believed to be an
                                                                  // imprecise whole-method re-run that could double-execute that side
                                                                  // effect (the real, once-confirmed Liquibase `Scope` corruption). That
                                                                  // premise is stale: the SAME day, a concurrent fix
                                                                  // (`docs/internal/jit-invokedynamic-uncommon-trap-precise-resume-groovy-regression-FIXED.md`)
                                                                  // closed FOUR separate bugs in the reason-8 (`UnreachedCode`) precise-resume
                                                                  // machinery this trap already uses UNCONDITIONALLY (`emit_osr_exit_map_at_reason`
                                                                  // below, `emit_deopt_stubs`'s reason-8 routing, not gated behind
                                                                  // `deopt_real_enabled()`) — including the exact nested-compiled-callee
                                                                  // identity-mismatch case this gate was defending against
                                                                  // (`try_resume_trapped_callee` + baked `method_key` identity checks,
                                                                  // verified via a dedicated repro: 30000/30000 corrupted calls before,
                                                                  // 0 after). A live indy trap today precisely resumes at the trapping bci
                                                                  // with the correct locals/stack reconstructed — it does not re-run
                                                                  // anything before it, so there is nothing left to double-execute. Removed
                                                                  // this scan-time gate; the underlying runtime protection it was
                                                                  // duplicating (imprecisely, at compile time) already exists and is
                                                                  // strictly more precise.
    let mut pc = 0;
    while pc < code_len {
        let op = code[pc];
        match op {
            // nop
            0x00 => {
                pc += 1;
            }
            // aconst_null
            0x01 => {
                pc += 1;
            }
            // iconst_m1..iconst_5
            0x02..=0x08 => {
                pc += 1;
            }
            // lconst_0, lconst_1
            0x09 | 0x0a => {
                pc += 1;
            }
            // fconst_0, fconst_1, fconst_2
            0x0b..=0x0d => {
                pc += 1;
            }
            // dconst_0, dconst_1
            0x0e | 0x0f => {
                pc += 1;
            }
            // bipush
            0x10 => {
                if pc + 1 >= code_len {
                    return None;
                }
                pc += 2;
            }
            // sipush
            0x11 => {
                if pc + 2 >= code_len {
                    return None;
                }
                pc += 3;
            }
            // iload, lload, fload, dload, aload (wide index)
            0x15..=0x19 => {
                if pc + 1 >= code_len {
                    return None;
                }
                local_slot_ops.push((pc, false, code[pc + 1] as u16));
                pc += 2;
            }
            // iload_0..iload_3
            0x1a..=0x1d => {
                local_slot_ops.push((pc, false, (op - 0x1a) as u16));
                pc += 1;
            }
            // lload_0..lload_3
            0x1e..=0x21 => {
                local_slot_ops.push((pc, false, (op - 0x1e) as u16));
                pc += 1;
            }
            // fload_0..fload_3, dload_0..dload_3
            0x22..=0x29 => {
                local_slot_ops.push((pc, false, ((op - 0x22) % 4) as u16));
                pc += 1;
            }
            // aload_0..aload_3
            0x2a..=0x2d => {
                local_slot_ops.push((pc, false, (op - 0x2a) as u16));
                pc += 1;
            }
            // iaload, laload, faload, daload, aaload, baload, caload, saload
            0x2e..=0x35 => {
                pc += 1;
            }
            // istore, lstore, fstore, dstore, astore (wide index)
            0x36..=0x3a => {
                if pc + 1 >= code_len {
                    return None;
                }
                local_slot_ops.push((pc, true, code[pc + 1] as u16));
                pc += 2;
            }
            // istore_0..istore_3
            0x3b..=0x3e => {
                local_slot_ops.push((pc, true, (op - 0x3b) as u16));
                pc += 1;
            }
            // lstore_0..lstore_3
            0x3f..=0x42 => {
                local_slot_ops.push((pc, true, (op - 0x3f) as u16));
                pc += 1;
            }
            // fstore_0..fstore_3, dstore_0..dstore_3
            0x43..=0x4a => {
                local_slot_ops.push((pc, true, ((op - 0x43) % 4) as u16));
                pc += 1;
            }
            // astore_0..astore_3
            0x4b..=0x4e => {
                local_slot_ops.push((pc, true, (op - 0x4b) as u16));
                pc += 1;
            }
            // iastore, lastore, fastore, dastore, aastore, bastore, castore, sastore
            0x4f..=0x56 => {
                // `aastore` (0x53) emits the SATB pre-write + post-store write
                // barriers, both of which load the VM pointer from
                // `heap_local_offset`. Without `needs_heap` that slot is never
                // set up (offset 0 aliases local 0), so the barrier calls
                // `jit_satb_pre_write_barrier` with a stack address as `vm_ptr`
                // → `vm.heap` dereferences garbage → SIGSEGV (H2 TestUtils,
                // JIT-only; the primitive array stores do inline stores with no
                // heap-dependent helper).
                if op == 0x53 {
                    needs_heap = true;
                }
                pc += 1;
            }
            // pop
            0x57 => {
                pc += 1;
            }
            // dup
            0x59 => {
                pc += 1;
            }
            // swap
            0x5f => {
                pc += 1;
            }
            // iadd..ddiv (all int/long/float/double add/sub/mul/div)
            0x60..=0x6f => {
                pc += 1;
            }
            // irem, lrem, frem, drem. (frem/drem 0x72/0x73: only the optimizing
            // IR backend lowers them — via a CALL to the jit_frem/jit_drem fmod
            // helper. The single-pass backend has no codegen arm, so it bails
            // them through the `match op` catch-all (`return false`). Admitting
            // them at scan time lets the IR pipeline see the method instead of
            // rejecting it outright here; with the FP gate off the method still
            // bails to single-pass → interpreter, exactly as before.)
            0x70..=0x73 => {
                pc += 1;
            }
            // ineg, lneg, fneg, dneg
            0x74..=0x77 => {
                pc += 1;
            }
            // ishl, lshl
            0x78 | 0x79 => {
                pc += 1;
            }
            // ishr, lshr
            0x7a | 0x7b => {
                pc += 1;
            }
            // iushr, lushr
            0x7c | 0x7d => {
                pc += 1;
            }
            // iand, land
            0x7e | 0x7f => {
                pc += 1;
            }
            // ior, lor
            0x80 | 0x81 => {
                pc += 1;
            }
            // ixor, lxor
            0x82 | 0x83 => {
                pc += 1;
            }
            // iinc — reads then writes the same slot, in that order (the
            // read-half must see whatever safety state existed BEFORE this
            // instruction; the write-half is what makes the slot safe for
            // anything after).
            0x84 => {
                if pc + 2 >= code_len {
                    return None;
                }
                local_slot_ops.push((pc, false, code[pc + 1] as u16));
                local_slot_ops.push((pc, true, code[pc + 1] as u16));
                pc += 3;
            }
            // i2l, i2f, i2d, l2i, l2f, l2d, f2i, f2l, f2d, d2i, d2l, d2f, i2b, i2c, i2s
            0x85..=0x93 => {
                pc += 1;
            }
            // lcmp, fcmpl, fcmpg, dcmpl, dcmpg
            0x94..=0x98 => {
                pc += 1;
            }
            // ifeq, ifne, iflt, ifge, ifgt, ifle
            0x99..=0x9e => {
                if pc + 2 >= code_len {
                    return None;
                }
                pc += 3;
            }
            // if_icmpeq..if_icmple
            0x9f..=0xa4 => {
                if pc + 2 >= code_len {
                    return None;
                }
                pc += 3;
            }
            // goto
            0xa7 => {
                if pc + 2 >= code_len {
                    return None;
                }
                pc += 3;
            }
            // ireturn, lreturn, freturn, dreturn
            0xac..=0xaf => {
                pc += 1;
            }
            // return (void)
            0xb1 => {
                pc += 1;
            }
            // invokestatic — track in invoke_ops for resolution (self-call or cross-method).
            // Always set needs_heap because cross-method dispatch via
            // jit_invoke_dispatch requires vm_ptr stored at heap_local_offset.
            0xb8 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                invoke_ops.push((pc, cp_idx, op));
                needs_heap = true;
                pc += 3;
            }
            // areturn — return object reference
            0xb0 => {
                pc += 1;
            }
            // getstatic — static field read (needs vm context)
            0xb2 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                static_field_ops.push((pc, cp_idx));
                needs_heap = true;
                pc += 3;
            }
            // putstatic — static field write (needs vm context)
            0xb3 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                static_field_ops.push((pc, cp_idx));
                needs_heap = true;
                pc += 3;
            }
            // getfield — object field read
            0xb4 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                field_ops.push((pc, cp_idx));
                // Default getfield codegen routes through the checked helper,
                // which needs the hidden SharedVm pointer. Reserving the
                // context slot is harmless when raw inlining is explicitly
                // enabled.
                needs_heap = true;
                pc += 3;
            }
            // putfield — object field write. A reference-typed putfield
            // lowers to a `jit_putfield_object(vm_ptr, ...)` helper call
            // (write barrier + SATB barrier), so the compiled method MUST
            // carry the hidden VM pointer. Without `needs_heap` the
            // codegen loads `vm_ptr` from `heap_local_offset == 0`, i.e.
            // `[rbp-0]` — the saved RBP — and hands that stack address to
            // `jit_putfield_object`, which then dereferences it as a
            // `SharedVm`: silent heap corruption that surfaced as a
            // delayed SIGSEGV (Tomcat's `Catalina.setParentClassLoader`,
            // a bare `aload_0; aload_1; putfield; return` with no other
            // heap op to set the flag).
            0xb5 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                field_ops.push((pc, cp_idx));
                needs_heap = true;
                pc += 3;
            }
            // newarray — needs heap for allocation
            0xbc => {
                if pc + 1 >= code_len {
                    return None;
                }
                has_newarray = true;
                needs_heap = true;
                pc += 2;
            }
            // arraylength
            0xbe => {
                pc += 1;
            }
            // checkcast — type check (pass-through or exception)
            0xc0 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                typecheck_ops.push((pc, cp_idx));
                needs_heap = true;
                pc += 3;
            }
            // instanceof — type check (returns 0 or 1)
            0xc1 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                typecheck_ops.push((pc, cp_idx));
                needs_heap = true;
                pc += 3;
            }
            // multianewarray — multi-dimensional array allocation (2D only for now)
            0xc5 => {
                if pc + 3 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                let ndims = code[pc + 3];
                if ndims != 2 {
                    return None;
                }
                multianewarray_ops.push((pc, cp_idx, ndims));
                needs_heap = true;
                pc += 4;
            }
            // if_acmpeq, if_acmpne — reference comparison branches
            0xa5 | 0xa6 => {
                if pc + 2 >= code_len {
                    return None;
                }
                pc += 3;
            }
            // ifnull, ifnonnull — null check branches
            0xc6 | 0xc7 => {
                if pc + 2 >= code_len {
                    return None;
                }
                pc += 3;
            }
            // invokevirtual, invokespecial — method dispatch via helper
            0xb6 | 0xb7 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                invoke_ops.push((pc, cp_idx, op));
                needs_heap = true;
                pc += 3;
            }
            // invokeinterface — interface dispatch via helper (5 bytes: opcode, cp_hi, cp_lo, count, 0)
            0xb9 => {
                if pc + 4 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                invoke_ops.push((pc, cp_idx, op));
                needs_heap = true;
                pc += 5;
            }
            // invokedynamic — no longer a permanent scan-time veto (5 bytes:
            // opcode, cp_hi, cp_lo, 0, 0). The overwhelmingly common source of
            // an invokedynamic in otherwise-ordinary hot methods is
            // `assert cond : "msg" + var;` (javac lowers the message concat via
            // `StringConcatFactory`), which sits on the assertions-disabled dead
            // branch. Previously ANY invokedynamic anywhere in a method's
            // bytecode — reachable or not — permanently blacklisted the WHOLE
            // method from JIT compilation (see the removed RG.1 test), forcing
            // hot per-call-site methods that merely CONTAIN a dead assert into
            // the interpreter forever.
            //
            // This scanner is CP-blind by design and does not resolve the
            // target descriptor — it just records the site (pc, cp_index) so
            // the codegen (which DOES have CP access) can look up the
            // descriptor later. The codegen lowers the instruction to an
            // unconditional jump to the existing uncommon-trap deopt stub
            // (`DeoptReason::UnreachedCode`): if this exact program point is
            // ever actually reached at runtime (assertions enabled, or a
            // genuinely live indy), the method permanently reverts to
            // interpreter-only execution for the rest of the process — i.e.
            // today's status quo for that one method. In the common case
            // (assertions disabled, dead branch) the trap is never taken and
            // the surrounding hot method compiles and runs at full JIT speed.
            //
            // REGRESSION FIX (2026-07-04): the unconditional-deopt codegen for
            // this opcode (the `0xba` arm in `compile_bytecode`, and the shared
            // `emit_deopt_stubs` out-of-line trap it jumps to) calls
            // `jit_uncommon_trap(vm_ptr, reason, bci)`, and loads `vm_ptr` from
            // `self.heap_local_offset` -- EXACTLY the same hidden-VM-pointer
            // frame slot documented above at the `aastore` (0x53) arm. That
            // slot is only reserved when `needs_heap` is set; otherwise
            // `heap_local_offset` aliases local slot 0 (see the `aastore`
            // comment), and the trap helper receives whatever garbage/local
            // value happens to sit there instead of the real `&SharedVm`,
            // which it blindly dereferences -- SIGSEGV. A method containing an
            // invokedynamic but no OTHER heap-requiring opcode (the common
            // dead-`assert` case is often exactly this shape) left
            // `needs_heap` false, so the very trap this fix relies on as its
            // "safe fallback" was itself unsafe. Set `needs_heap = true` here,
            // mirroring every other opcode whose codegen depends on
            // `heap_local_offset` (invoke*, new, anewarray, aastore, ...).
            0xba => {
                if pc + 4 >= code_len {
                    return None;
                }
                // BUG-LQB-SCOPE gate removed — see the doc comment above
                // (where `first_committing_side_effect_pc` used to be
                // declared) for why it's no longer needed.
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                indy_ops.push((pc, cp_idx));
                needs_heap = true;
                pc += 5;
            }
            // tableswitch — accept in scanner, emit CMP chain in compiler
            0xaa => {
                pc += 1;
                while pc % 4 != 0 && pc < code_len {
                    pc += 1;
                }
                let header_end = pc.checked_add(12)?;
                if header_end > code_len {
                    return None;
                }
                let low =
                    i32::from_be_bytes([code[pc + 4], code[pc + 5], code[pc + 6], code[pc + 7]]);
                let high =
                    i32::from_be_bytes([code[pc + 8], code[pc + 9], code[pc + 10], code[pc + 11]]);
                // Checked `high - low + 1`: raw i32 arithmetic overflows on
                // attacker-controlled bounds. Bail (not JIT-eligible) on
                // overflow or an out-of-range count.
                let num_offsets = match checked_tableswitch_count(low, high) {
                    Some(n) => n,
                    None => return None,
                };
                let payload_bytes = num_offsets.checked_mul(4)?;
                let switch_end = header_end.checked_add(payload_bytes)?;
                if switch_end > code_len {
                    return None;
                }
                pc = switch_end;
            }
            // lookupswitch — accept in scanner, emit CMP chain in compiler
            0xab => {
                pc += 1;
                while pc % 4 != 0 && pc < code_len {
                    pc += 1;
                }
                let header_end = pc.checked_add(8)?;
                if header_end > code_len {
                    return None;
                }
                let npairs_raw =
                    i32::from_be_bytes([code[pc + 4], code[pc + 5], code[pc + 6], code[pc + 7]]);
                let npairs = match checked_lookupswitch_npairs(npairs_raw) {
                    Some(n) => n,
                    None => return None,
                };
                let payload_bytes = npairs.checked_mul(8)?;
                let switch_end = header_end.checked_add(payload_bytes)?;
                if switch_end > code_len {
                    return None;
                }
                pc = switch_end;
            }
            // ldc — load int/float/string constant from CP (1-byte index)
            0x12 => {
                if pc + 1 >= code_len {
                    return None;
                }
                let cp_idx = code[pc + 1] as u16; // Widening: always safe
                ldc_ops.push((pc, cp_idx));
                pc += 2;
            }
            // ldc_w — load int/float/string constant from CP (2-byte index)
            0x13 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                ldc_ops.push((pc, cp_idx));
                pc += 3;
            }
            // ldc2_w — load long/double constant from CP (2-byte index)
            0x14 => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                ldc2w_ops.push((pc, cp_idx));
                pc += 3;
            }
            // pop2 — discard top two slots
            0x58 => {
                pc += 1;
            }
            // dup_x1 — duplicate top and insert two below
            0x5a => {
                pc += 1;
            }
            // dup_x2 — duplicate top and insert three below
            0x5b => {
                pc += 1;
            }
            // dup2 — duplicate top two slots
            0x5c => {
                pc += 1;
            }
            // dup2_x1 — duplicate top two and insert three below
            0x5d => {
                pc += 1;
            }
            // dup2_x2 — duplicate top two and insert four below
            0x5e => {
                pc += 1;
            }
            // new — object allocation; tracked for code generation
            0xbb => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                new_ops.push((pc, cp_idx));
                needs_heap = true;
                pc += 3;
            }
            // anewarray — reference array allocation; tracked for code generation
            0xbd => {
                if pc + 2 >= code_len {
                    return None;
                }
                let cp_idx = ((code[pc + 1] as u16) << 8) | (code[pc + 2] as u16); // Widening: always safe
                anewarray_ops.push((pc, cp_idx));
                needs_heap = true;
                pc += 3;
            }
            // monitorenter / monitorexit. Non-escaping locks are elided;
            // live locks call the VM's direct mark-word helper, which needs
            // the hidden VM context just like allocation/field helpers.
            0xC2 | 0xC3 => {
                needs_heap = true;
                pc += 1;
            }
            // RBC.6 — athrow. Accepted; `has_athrow` is recorded so callers
            // can gate compilation to methods WITHOUT local exception
            // handlers (the codegen lowers athrow to "stash pending
            // exception + return the i64::MIN deopt sentinel", which cannot
            // dispatch to an in-method handler) and so the OSR trigger can
            // decline (its bail path resumes at the back-edge, which could
            // re-run side effects). `analyze_escapes` already treats 0xbf
            // as a full-escape barrier, so scalar replacement stays sound.
            0xbf => {
                has_athrow = true;
                pc += 1;
            }
            // Anything else: not JIT-compatible
            _ => {
                if cratonvm_types::flags::runtime_var_os("CRATONVM_DBG_JITC").is_some() {
                    eprintln!("[cratonvm-jitc] scan-bail op=0x{:02x} pc={}", op, pc);
                }
                return None;
            }
        }
    }

    // Check the return type is int, long, float, double, object reference, or void
    let ret = super::return_type(descriptor);
    if !matches!(
        ret,
        b'I' | b'J' | b'F' | b'D' | b'[' | b'L' | b'V' | b'B' | b'C' | b'S' | b'Z'
    ) {
        return None;
    }

    // DUP2 category handling now lives in the codegen (`compile_bytecode`'s
    // 0x5C arm via `dup2_top_cat2`). Unlike this CP-less scan, the codegen
    // resolves `getfield`/`getstatic`/`invoke*` descriptors, so it can tell a
    // FORM-2 (single category-2 long/double) `dup2` from a FORM-1 (two
    // category-1) one and emit each correctly — bailing to the interpreter only
    // when the top width is genuinely unprovable. The old `dup2_category_safe`
    // reject gate that sat here over-rejected FORM-1 methods (any
    // `<getfield/invoke>; dup2` whose result is category-1, which the CP-less
    // scan could not prove), de-JITing a bintrees18-hot method and regressing
    // it to a heap-walker desync + throughput cliff — so the blanket reject is
    // removed in favour of the precise codegen handling.

    // Run a *conservative* escape pre-pass here: `jit_scan` has no
    // constant-pool resolver, so it cannot tell a trivial `<init>()V`
    // apart from an arg-bearing constructor. We therefore pass an empty
    // shape map (every `invokespecial` escapes its operands). The
    // precise pass — which re-enables scalar replacement for the
    // `new; dup; invokespecial <init>()V` pattern — runs later in
    // `compile_bytecode`, where the resolved invoke descriptors are
    // available, and overwrites this set.
    let non_escaping_new = if new_ops.is_empty() {
        std::collections::HashSet::new()
    } else {
        analyze_escapes(code, code_len, &FxHashMap::default())
    };

    Some(JitScanResult {
        needs_heap,
        multianewarray_ops,
        field_ops,
        typecheck_ops,
        static_field_ops,
        invoke_ops,
        new_ops,
        anewarray_ops,
        non_escaping_new,
        ldc_ops,
        ldc2w_ops,
        indy_ops,
        has_athrow,
        has_newarray,
        local_slot_ops,
    })
}

/// Result of scanning bytecode for JIT compatibility.
pub struct JitScanResult {
    pub needs_heap: bool,
    /// For each multianewarray instruction: (bytecode_pc, cp_index, ndims)
    pub multianewarray_ops: Vec<(usize, u16, u8)>,
    /// For each getfield/putfield instruction: (bytecode_pc, cp_index)
    pub field_ops: Vec<(usize, u16)>,
    /// For each checkcast/instanceof instruction: (bytecode_pc, cp_index)
    pub typecheck_ops: Vec<(usize, u16)>,
    /// For each getstatic/putstatic instruction: (bytecode_pc, cp_index)
    pub static_field_ops: Vec<(usize, u16)>,
    /// For each invoke instruction: (bytecode_pc, cp_index, opcode)
    pub invoke_ops: Vec<(usize, u16, u8)>,
    /// For each `new` (0xbb) instruction: (bytecode_pc, cp_index)
    pub new_ops: Vec<(usize, u16)>,
    /// For each `anewarray` (0xbd) instruction: (bytecode_pc, cp_index)
    pub anewarray_ops: Vec<(usize, u16)>,
    /// Set of `new` bytecode PCs whose objects are non-escaping (candidates for scalar replacement).
    pub non_escaping_new: std::collections::HashSet<usize>,
    /// For each `ldc`/`ldc_w` (0x12, 0x13) instruction: (bytecode_pc, cp_index)
    pub ldc_ops: Vec<(usize, u16)>,
    /// For each `ldc2_w` (0x14) instruction: (bytecode_pc, cp_index)
    pub ldc2w_ops: Vec<(usize, u16)>,
    /// For each `invokedynamic` (0xba) instruction: (bytecode_pc, cp_index).
    /// The codegen resolves each site's target descriptor (this CP-less scan
    /// cannot) and lowers the instruction to an unconditional deopt to the
    /// interpreter via `DeoptReason::UnreachedCode` — see the 0xba codegen arm.
    pub indy_ops: Vec<(usize, u16)>,
    /// RBC.6 — the method contains `athrow` (0xbf). Never OSR-eligible
    /// (declined unconditionally in the OSR trigger, since the OSR bail
    /// path resumes at the back-edge and could re-run side effects). A
    /// method combining this with a non-empty local exception table is now
    /// compilable — see `docs/feature-designs/jit-local-exception-handlers.md`
    /// — subject to `local_handler_reads_unsafe_local`'s check on
    /// `local_slot_ops` below.
    pub has_athrow: bool,
    /// The method contains primitive `newarray` (0xbc).
    pub has_newarray: bool,
    /// RBC.6 local-handler-safety fix — every `*load`/`*store`/`iinc`
    /// instruction's `(bytecode_pc, is_store, local_slot)`, in bytecode
    /// order. See the field's push sites in `jit_scan` and
    /// `local_handler_reads_unsafe_local` (jit/src/lib.rs) for how this is
    /// used to conservatively verify a method's local exception handler(s)
    /// never observe a local the JIT's params-only handler-frame
    /// reconstruction (`route_jit_exception_through_method`) cannot
    /// recover.
    pub local_slot_ops: Vec<(usize, bool, u16)>,
}

/// Check if a bytecode method can be JIT-compiled (backward-compatible wrapper).
pub fn is_jit_compatible(code: &[u8], code_len: usize, descriptor: &str) -> bool {
    jit_scan(code, code_len, descriptor).is_some()
}

// ---------------------------------------------------------------------------
// Loop-Invariant Code Motion (LICM)
// ---------------------------------------------------------------------------

/// A loop-invariant `aload X; iload Y; aaload` sequence that can be hoisted
/// out of a loop body. The hoisted value (a row pointer from an Object[][] array)
/// is computed once before the loop and cached in a spill slot.
struct LoopHoist {
    /// Bytecode PC of the loop header (back-edge target).
    loop_header: usize,
    /// First PC strictly after the back-edge instruction (`loop_end`).
    /// All PCs `p` with `loop_header <= p < loop_end` are part of the loop
    /// body. Tracked here so the OSR entry path can detect when a PC lives
    /// inside a hoisted loop without re-running `detect_loops`.
    loop_end: usize,
    /// First bytecode PC of the invariant sequence (the aload instruction).
    seq_start: usize,
    /// Bytecode PC after the invariant sequence (past the aaload).
    seq_end: usize,
    /// Local variable index for the array reference.
    array_local: usize,
    /// Local variable index for the array index.
    index_local: usize,
}

/// Information about a loop-invariant FP load that can be hoisted.
/// Pattern: dload/fload of a local that is not modified within the loop body.
#[derive(Debug)]
#[allow(dead_code)]
struct FpLoopHoist {
    /// Bytecode PC of the loop header (back-edge target).
    loop_header: usize,
    /// Bytecode PC of the invariant dload/fload instruction.
    load_pc: usize,
    /// Local variable index being loaded.
    local_idx: usize,
    /// true = double (dload), false = float (fload).
    is_double: bool,
}

/// Information about a vectorizable double-array sum reduction loop.
/// Pattern: for (i = start; i < bound; i++) sum += arr[i]
/// where arr is a double[] and sum is a double local.
#[derive(Debug)]
#[allow(dead_code)]
struct SimdFpArraySum {
    /// Bytecode PC of the loop header.
    header_pc: usize,
    /// Bytecode PC of the back-edge instruction.
    back_edge_pc: usize,
    /// Local index of the induction variable (i).
    iv_local: usize,
    /// Local index of the accumulator (sum).
    acc_local: usize,
    /// Local index of the array reference.
    array_local: usize,
    /// Local index of the loop bound.
    bound_local: usize,
    /// Operation: 0x58=ADD (sum), 0x59=MUL (dot product partial).
    sse_op: u8,
}

/// Get the byte length of a bytecode instruction at `pc`.
pub(crate) fn bytecode_len_at(code: &[u8], pc: usize) -> usize {
    match code[pc] {
        // 2-byte: bipush(0x10), ldc(0x12), iload..aload(0x15..0x19),
        // istore..astore(0x36..0x3a), ret(0xa9), newarray(0xbc).
        // `ldc` (0x12) was previously absent and fell through to the `_ => 1`
        // arm — a 1-byte under-count that misaligned every PC-stepping consumer
        // (branch-target precompute, DCE, OSR/unroll). When an `ldc` sat
        // immediately before a branch (e.g. `ldc 65536; if_icmpge exit` — the
        // standard `for (i; i<CONST; …)` header), the scan skipped the branch,
        // never marked its exit target, DCE-killed that target, and left the
        // loop-exit `if_icmpge` unpatched (rel32=0) → the loop overran its bound
        // (BC SPHINCS-256 Horst.horst_sign AIOOBE).
        0x10 | 0x12 | 0x15..=0x19 | 0x36..=0x3a | 0xa9 | 0xbc => 2,
        // 3-byte: sipush(0x11), ldc_w(0x13), ldc2_w(0x14), iinc(0x84), jsr(0xa8),
        // the if_* family, field/invoke ops, etc. ldc_w/ldc2_w were also absent.
        0x11
        | 0x13
        | 0x14
        | 0x84
        | 0xa8
        | 0x99..=0xa6
        | 0xa7
        | 0xb2
        | 0xb3
        | 0xb4
        | 0xb5
        | 0xb6
        | 0xb7
        | 0xb8
        | 0xbd
        | 0xc0
        | 0xc1
        | 0xc6
        | 0xc7 => 3,
        0xbb => 3, // new
        0xc5 => 4,
        // 5-byte instructions. invokeinterface (0xb9: opcode, cp_hi, cp_lo,
        // count, 0) and invokedynamic (0xba: opcode, cp_hi, cp_lo, 0, 0) are
        // both reachable in a compiled method today (`jit_scan` accepts
        // both). The wide-offset branches goto_w (0xc8) / jsr_w (0xc9:
        // opcode + 4-byte signed offset) are still rejected by `jit_scan`
        // (catch-all → `None`), so no compiled method contains them — but,
        // like `wide` (0xc4) below, the length table must stay correct as
        // defense-in-depth so every PC-stepping consumer (branch-target
        // precompute, DCE, OSR/unroll, instruction-start map, oop-map dataflow)
        // stays in lockstep if any is ever accepted. A missing entry
        // under-counts by 4 bytes and misaligns the walk — the same class of
        // bug as the previously-absent `ldc`. Keep the regalloc.rs `bc_len`
        // twin in sync.
        0xb9 | 0xba | 0xc8 | 0xc9 => 5,
        // wide (0xc4) — prefix modifies the following opcode to use a 2-byte
        // local index. JVMS §6.5 wide: `wide <opcode> <indexbyte1> <indexbyte2>`
        // is 4 bytes for the load/store/ret family, and `wide iinc <index>
        // <const>` is 6 bytes (extra 2-byte signed constant). The modified
        // opcode is the byte at `pc + 1`: only `iinc` (0x84) takes the 6-byte
        // form. Currently latent — `jit_scan` rejects `wide`, so no compiled
        // method contains it — but the length table must stay correct as
        // defense-in-depth so every PC-stepping consumer stays in lockstep if
        // `wide` is ever accepted. Keep the regalloc.rs `bc_len` twin in sync.
        0xc4 => {
            if pc + 1 < code.len() && code[pc + 1] == 0x84 {
                6 // wide iinc
            } else {
                4 // wide <load/store/ret>
            }
        }
        // tableswitch — variable length
        0xaa => {
            let mut p = pc + 1;
            while p % 4 != 0 {
                p += 1;
            }
            // Truncated header: a tableswitch placed near the end of `code` may
            // not carry the full 12-byte default/low/high header. Reading it
            // would index past `code_len` and panic. Return a length that
            // consumes the rest of `code` so any walker that uses this helper
            // terminates without an OOB read; the main compile loop's own
            // `pc + 12 > code_len` guard then rejects the method.
            if p + 12 > code.len() {
                return code.len() - pc;
            }
            let low = i32::from_be_bytes([code[p + 4], code[p + 5], code[p + 6], code[p + 7]]);
            let high = i32::from_be_bytes([code[p + 8], code[p + 9], code[p + 10], code[p + 11]]);
            // Checked `high - low + 1`: raw i32 arithmetic overflows on
            // attacker-controlled bounds. Such methods are already rejected by
            // `jit_scan`; if one ever reaches here, fall back to a zero count
            // (header-only length) rather than overflowing the address math.
            let count = checked_tableswitch_count(low, high).unwrap_or(0);
            (p + 12 + count * 4) - pc
        }
        // lookupswitch — variable length
        0xab => {
            let mut p = pc + 1;
            while p % 4 != 0 {
                p += 1;
            }
            // Truncated header (see tableswitch above): bail to a remainder
            // length rather than reading the 8-byte default/npairs header OOB.
            if p + 8 > code.len() {
                return code.len() - pc;
            }
            // A negative `npairs` (crafted bytecode) cast straight to usize would
            // become an enormous value and overflow the address math below; clamp
            // to 0 so the length stays sane (the main loop rejects such methods).
            let npairs = i32::from_be_bytes([code[p + 4], code[p + 5], code[p + 6], code[p + 7]])
                .max(0) as usize; // Widening: always safe
            (p + 8 + npairs * 8) - pc
        }
        _ => 1,
    }
}

/// array_receiver_local soundness fix — build a bitmap of valid instruction
/// START offsets for `code[..code_len]`.
///
/// Backward scans (e.g. reading `code[pc - 1]` and guessing the opcode) are
/// unsound: a multi-byte instruction's trailing OPERAND byte can collide with
/// a real opcode value, so a naive "previous byte" decode mis-identifies the
/// instruction. The only reliable way to know whether a given offset is an
/// instruction boundary is to walk FORWARD from PC 0 stepping by
/// [`bytecode_len_at`] (the same walk used by [`compute_branch_targets`] and
/// the oop-map dataflow). `starts[k]` is `true` iff `k` is the first byte of
/// some instruction reached by that linear walk.
///
/// Callers use this to *validate* a candidate instruction position before
/// trusting a backward-derived decode; when the candidate is not a real
/// instruction start the caller must fall back to the conservative path.
fn instruction_start_map(code: &[u8], code_len: usize) -> Vec<bool> {
    let mut starts = vec![false; code_len];
    let mut pc = 0usize;
    while pc < code_len {
        starts[pc] = true;
        let len = bytecode_len_at(code, pc).max(1); // never advance 0 → no infinite loop
        pc += len;
    }
    starts
}

/// EC-SCALAR-SOUNDNESS (bc math-ec JIT miscompile fix) — compute the set of
/// bytecode PCs that are the TARGET of any branch (conditional, `goto`,
/// `goto_w`, `jsr`, `jsr_w`, `tableswitch`, `lookupswitch`).
///
/// The single-linear-pass escape / scalar-replacement analyses
/// (`analyze_escapes`, `plan_scalar_replacement`) carry abstract operand-stack
/// and per-local provenance straight through the bytecode without resetting at
/// basic-block boundaries. That is only sound for straight-line code: at a
/// merge point (a branch target reachable from more than one predecessor) the
/// linear state need not match the real verification-time state on every
/// incoming edge. To keep those analyses sound we treat every branch *source*
/// (handled inline at each branch opcode) AND every branch *target* (via this
/// set) as a hard barrier that drops all tracked provenance, confining any
/// scalar-replaced object to a single-entry / single-exit straight-line
/// region.
///
/// Returns a bit-set (`Vec<bool>` indexed by PC) of size `code_len`.
/// Stage 3 (precise oop maps) — process-wide gate for the *moving*-safe
/// precise-stack-map machinery (exact RBP frame registration, safepoint-id
/// slot, precise relocation).
///
/// **DEFAULT ON** (re-flipped 2026-07-07). Opt out with `CRATONVM_NO_PRECISE_JIT_MAPS=1`.
/// (`CRATONVM_PRECISE_JIT_MAPS` is now a no-op — the coverage is the default.)
///
/// The BUG-01 ~6× throughput tax that had motivated the d53c0e96 default-OFF flip
/// is **gone on current dev**: intervening JIT improvements (more inlining → far
/// fewer real call safepoints in the hot reflection/framework methods) cut the
/// precise per-safepoint cost to noise. Measured 2026-07-07 on the Linux
/// spring-core suite: `ObjectUtilsTests`/`ClassUtilsTests` are byte-for-byte the
/// same wall time precise-on vs -off even at `JIT_THRESHOLD=50`; a 40-class
/// spring-util reflection batch is 73.5 s on vs 70.5 s off (~4%) with **identical
/// pass counts (1059/1061)**. GC-root coverage verified on with it: `binarytrees
/// 14 @GC_STRESS=4096` → `3222190` clean, and the Fork6 GC_STRESS outcome A/B is
/// 14/15 ALL-OK on == off (the higher young-mark marker count under precise-on is
/// benign guard-contained over-retention, not worse outcomes). See BUG-01 doc:
/// `docs/internal/app-jvm-bugs/bug-01-junit-reflection-heavy-jit-frame-scan-throughput.md`.
///
/// History: default-OFF (d53c0e96) for BUG-01: the per-invocation
/// `frame_record` + per-safepoint sp-id/flush codegen was a ~6× throughput tax on
/// call-heavy JIT'd code (JUnit execution: 105 s → 18 s with this off) on that
/// era's build.
///
/// TRADE-OFF (accepted, residuals tracked): when off, the GC falls back to the
/// conservative deepest-band-only JIT-frame scan, which can miss a live oop held
/// only in a callee-saved register of a *caller* frame — the GC-root-coverage-under-JIT
/// family (SB-CRASH-04 / A2 ReflRepro / A4 Fork6) this machinery was landed to fix
/// (commit 5b8864a0). Opt back in with `CRATONVM_PRECISE_JIT_MAPS=1` to restore that
/// coverage. The follow-up fix is to keep the coverage while cutting the per-call cost
/// (RBP-chain walk at GC time, or selective emission); see the BUG-01 doc.
///
/// When off, no Stage 3 codegen is emitted (byte-identical legacy path); when on,
/// bintrees16/18 == golden (14985902 / 68332206), MinRegexProbe A3 repro green.
pub fn precise_jit_maps_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        // Flipped back to DEFAULT-ON 2026-07-07 (see the doc comment above):
        // the BUG-01 ~6× throughput tax that motivated the d53c0e96 default-off
        // flip is gone on current dev. Opt out with CRATONVM_NO_PRECISE_JIT_MAPS=1.
        cratonvm_types::flags::runtime_var_os("CRATONVM_NO_PRECISE_JIT_MAPS").is_none()
    })
}

/// Default-on inline reference-`putfield` fast path.
///
/// When on, a `putfield` of a reference field emits an inline 16-byte `Value`
/// store INSTEAD of the `jit_putfield_object` helper CALL when the field's OLD
/// value is null (`payload == 0`, so no SATB snapshot is needed). Young
/// receivers require no post barrier; old generational receivers use the
/// inline atomic card mark. Collector-specific G1/ZGC barriers and non-null
/// old values retain the validated helper. This is the canonical
/// fresh-object-initialisation pattern (`n.left = newChild`) that dominates
/// allocation-heavy code (object binarytrees). Opt out with
/// `CRATONVM_NO_JIT_INLINE_PUTFIELD`; the former
/// `CRATONVM_JIT_INLINE_PUTFIELD` opt-in is accepted as a compatibility no-op.
///
/// INT-6 (GC audit 2026-07-10): the YOUNG test reads `GC_FLAG_OLD_GEN`, which
/// only the GENERATIONAL backend maintains — under G1/ZGC every object read
/// as "young" and the fast path elided G1's RSet post-barrier for Old→young
/// stores. Both inline arms now prepend the guarded-getfield receiver check
/// (null/alignment/published-region containment): G1/ZGC never publish
/// region bounds, so every receiver bails to the full-barrier helper there,
/// making the switch safe to enable on any backend.
/// Whether narrow oops force every compact-field access through the helpers.
///
/// The inline compact-field fast paths bake an 8-byte reference load/store at a
/// compile-time offset. Under compressed oops a reference slot is 4 bytes
/// holding `(addr - base) >> shift`, so those emissions would read/write the
/// wrong width and the wrong value. Until the codegen learns to emit the narrow
/// load plus the base+shift transform, compressed oops disable the inline path
/// and `getfield`/`putfield` fall back to `jit_getfield` / `jit_putfield_object`,
/// which go through the width-aware `read_compact_field` / `write_compact_field`.
#[inline]
pub fn narrow_oops_block_inline_fields() -> bool {
    narrow_oops_enabled()
}

pub fn inline_putfield_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        cratonvm_types::flags::runtime_var_os("CRATONVM_NO_JIT_INLINE_PUTFIELD").is_none()
    })
}

/// Inline TLAB `new` — bump allocation emitted directly in compiled code.
///
/// Default-ON again (bt18-inline-tlab-regression-20260724): the emission is
/// now suspension- and walker-safe — the full object header is written
/// BEFORE the cursor-commit store, which is the single linearization point
/// (x86-64 TSO: stores are not reordered with older stores), and every
/// header field that historically relied on the "TLAB refill zeroes the
/// region" assumption is written explicitly. That closes the publication
/// race for which 1ee92e3fd demoted this path to opt-in — a demotion that
/// re-helperized the hottest allocation path and cost bt18 ~4x
/// (single-cycle 90%-fill young GC and the inline fresh-ctor stores both
/// sat on top of this path).
///
/// Opt out: `CRATONVM_NO_JIT_INLINE_TLAB_NEW=1` routes every `new` through
/// the always-correct `new_object` helper. The legacy opt-in
/// `CRATONVM_ENABLE_UNSAFE_INLINE_TLAB_NEW` remains accepted and is now
/// redundant.
pub fn inline_tlab_new_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        cratonvm_types::flags::runtime_var_os("CRATONVM_NO_JIT_INLINE_TLAB_NEW").is_none()
    })
}

fn inline_site_is_fresh_ctor_first_store(
    site: &crate::InlineSite,
    cpc: usize,
    field_index: usize,
) -> bool {
    site.method_name == "<init>"
        && !site.field_info.iter().any(|(prior_pc, prior_index, _)| {
            *prior_pc < cpc && *prior_index == field_index && site.callee_code[*prior_pc] == 0xb5
        })
}

/// Opt-IN inline `getfield` fast path (`CRATONVM_JIT_INLINE_GETFIELD`).
///
/// The raw inline path can only null-check the receiver before reading object
/// headers/field cells — no plausibility or containment validation at all.
/// Kept as an explicit opt-in for A/B measurement; the production default is
/// the GUARDED inline path below (`guarded_inline_getfield_enabled`), which
/// validates the receiver against the published heap-region bounds before the
/// raw load and falls back to the checked helper otherwise.
pub fn inline_getfield_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        cratonvm_types::flags::runtime_var_os("CRATONVM_JIT_INLINE_GETFIELD").is_some()
    })
}

/// Default-ON guarded inline `getfield` (perf/throughput-20260710).
///
/// The 2026-07-09 hardening (`Fix JIT getfield receiver validation`,
/// 85baa4219) routed EVERY default-path JIT `getfield` through the checked
/// `jit_getfield` helper. That closed the stale/garbage-receiver SIGSEGV
/// (Tomcat DoHead rc=139) but put a full helper round-trip — boundary note,
/// `is_object_address` region walk + header validation, 16-byte atomic cell
/// read — on one of the hottest ops the JIT emits: bintrees-16 regressed
/// 4.7x, and every field-heavy JIT workload (commons-math `Dfp`, Tomcat
/// serving) pays it on each field read.
///
/// The guarded inline path keeps the property that actually stops the SIGSEGV
/// — never dereference a receiver outside the always-mapped GC arenas — at
/// inline-check cost: null/alignment bit-tests plus the same three-region
/// `[base, end)` containment check that `is_object_address` uses as its
/// gate, reading the GC's process-global `JIT_REGION_BOUNDS` table whose
/// address the helpers table carries in `region_bounds_addr`. Receivers that
/// pass are raw-loaded inline (a mapped-arena read cannot fault); everything
/// else — null, unaligned garbage, out-of-heap bits, or a backend that does
/// not publish bounds (G1/ZGC → table all zeros) — branches to the checked
/// helper, preserving its NPE / `i64::MIN`-sentinel semantics exactly.
///
/// FLIPPED BACK OFF then RE-ENABLED, same day (2026-07-10): investigating the
/// ES DiversifyingChildrenIVFKnnFloatSlicedVectorQueryTests /
/// IVFKnnFloatVectorQueryTests hang cluster
/// (docs/known-issues/elasticsearch-suite/) found `testSlicesDense` under JIT
/// SIGSEGVing almost immediately with this path default-on (dmesg: `segfault
/// at 4c`, gdb: an AALOAD bounds-check dereferencing a receiver of `0x40` — a
/// small int value used as an array pointer, i.e. a getfield RESULT feeding a
/// later array access got corrupted) — the flag was flipped to opt-in
/// (`CRATONVM_JIT_GUARDED_GETFIELD=1`) pending root-cause. That root cause
/// was found and fixed the SAME DAY, in a different investigation
/// (the WildFly Host Controller invoke-inline-cache SIGSEGV): the vm-side JIT
/// field resolvers fabricated a `(0, false)` "compact slot" for any field
/// with NO genuine registered `CompactLayout` entry, and the compact-offset
/// inline getfield arm trusted it — a REFERENCE field with the fabricated
/// `is_ref=false` fell into the int-category match arm and got a 32-bit
/// `MOVSXD` load of half a `Value` cell, producing exactly this "small-int
/// garbage used as a pointer" shape. See
/// docs/internal/wildfly-domain-hostcontroller-sigsegv-inline-cache-null-receiver-FIXED.md
/// for the full chain. Re-verified clean with
/// `CRATONVM_JIT_GUARDED_GETFIELD=1` against the exact IVF-KNN repro (no
/// SIGSEGV, no dmesg segfault entry — only the separate, still-OPEN,
/// already-tracked Lucene IndexWriter/STW-monitor-race hang this doc's own
/// "underlying interpreter hang" section describes) — re-enabled default-ON.
/// `CRATONVM_JIT_GETFIELD_HELPER=1` restores the helper-only path if a new
/// corruption is ever suspected here again.
pub fn guarded_inline_getfield_enabled() -> bool {
    // NOT OnceLock-cached (unlike the other flags in this file): this is a
    // JIT COMPILE-TIME gate, read once per getfield call SITE during
    // compilation, never on the runtime hot path — so re-reading the env
    // var every call has no measurable cost. Caching it would make the
    // off-switch racy against whichever test/thread first triggers ANY
    // getfield compilation in the process.
    cratonvm_types::flags::runtime_var_os("CRATONVM_JIT_GETFIELD_HELPER").is_none()
}

/// Default-ON inline self-recursion stack check (perf/throughput-20260710).
///
/// A method with direct self-recursive call sites reserves one frame slot,
/// fills it once in the prologue from the leaf `jit_native_stack_floor`
/// helper, and each self-call site emits `CMP RSP, [rbp - floor_slot]; JA
/// <skip>` -- bypassing the `self_call_stack_guard` helper CALL (and its
/// safepoint spill / shadow push+reload bracketing) on the common path. The
/// helper call remains verbatim as the fallback and still owns the catchable
/// StackOverflowError raise; OSR trampolines initialise the slot to
/// `usize::MAX` so OSR-entered frames always take the helper.
/// `CRATONVM_JIT_INLINE_SELF_GUARD=0` restores the helper-per-call shape for
/// bisection.
pub fn inline_self_guard_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(
        || match cratonvm_types::flags::runtime_var("CRATONVM_JIT_INLINE_SELF_GUARD") {
            Ok(v) => v != "0" && !v.eq_ignore_ascii_case("false"),
            Err(_) => true,
        },
    )
}

/// Let direct self-recursive entries inherit immutable per-thread cache slots
/// from their caller frame after proving the return address belongs to this
/// method's private executable buffer. External entries retain the normal TLS
/// helper initialization. Opt out with `CRATONVM_JIT_NO_SELF_CACHE_INHERIT=1`.
fn self_cache_inherit_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        cratonvm_types::flags::runtime_var_os("CRATONVM_JIT_NO_SELF_CACHE_INHERIT").is_none()
    })
}

/// Step 1 of `docs/feature-designs/precise-jit-maps-default.md` — opt-IN
/// **inline** frame-record. When on (and precise maps are on, and the OS TLS
/// probe in [`inline_rbp_tls_disp`] succeeds), the JIT stores RBP straight into
/// the precise-maps innermost-RBP mirror with one segment-relative `mov`
/// (`gs:` on Windows, `fs:` on Linux) instead of `call jit_frame_record`.
/// This removes the per-invocation CALL that is the residual ~1.68× call-heavy
/// regression after the thread-local cache (`82cf85e9`) already cut the helper
/// body cost.
///
/// **DEFAULT ON** (Step 2 flip, 2026-06-21; opt out with
/// `CRATONVM_NO_PRECISE_INLINE_FRAME_RECORD`). Validated on the inlined path:
/// bintrees10/14/16/18 == HotSpot, fib44 ~1.68× faster than the CALL path, and
/// the `CRATONVM_DBG_VERIFY_INLINE_FRAME_RECORD` self-check is clean (0
/// mismatches over billions of fib44 invocations). Off → the existing
/// `call jit_frame_record` is emitted (the pre-Step-1 default). Only meaningful
/// with precise maps on (otherwise there is no frame-record at all), so it is
/// anded with [`precise_jit_maps_enabled`]. On an unsupported target or a failed
/// TLS probe, [`inline_rbp_tls_disp`] returns 0 and the CALL path is used even
/// when this is on.
pub fn precise_inline_frame_record_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        precise_jit_maps_enabled()
            && cratonvm_types::flags::runtime_var_os("CRATONVM_NO_PRECISE_INLINE_FRAME_RECORD")
                .is_none()
    })
}

/// Debug self-check (`CRATONVM_DBG_VERIFY_INLINE_FRAME_RECORD`): when on AND
/// inline frame-record is active, the prologue emits the inline store **and** a
/// call to the verify helper (wired into the `frame_record` slot by
/// `build_helpers`) which reads the mirror back and asserts it equals RBP —
/// proving the inlined store lands exactly where the Rust GC side reads it.
/// Default off; pure validation aid, no behaviour change to the mirror value.
pub fn verify_inline_frame_record_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    *G.get_or_init(|| {
        cratonvm_types::flags::runtime_var_os("CRATONVM_DBG_VERIFY_INLINE_FRAME_RECORD").is_some()
    })
}

/// Step 1 — the segment-relative byte displacement of the OS TLS slot that
/// backs the precise-maps innermost-RBP mirror, or `0` when inline frame-record
/// is disabled or unavailable. This is the **single source of truth** shared by
/// JIT codegen and the VM-side mirror accessor in
/// `vm/src/jit/conservative_roots.rs`. Computed once, cached for the process.
///
/// Windows x86-64 stores the 64 static TLS slots in the TEB at offset `0x1480`
/// (`TlsSlots`), reachable as `gs:[0x1480 + slot*8]`. We `TlsAlloc` a slot,
/// write a unique 64-bit sentinel through the documented `TlsSetValue` API,
/// then read it back through the candidate `gs:[disp]` to **prove** the
/// displacement before trusting it (with a fallback scan of the static band in
/// case the base constant differs). If the probe fails (slot ≥ 64, unexpected
/// TEB layout, or non-Windows), it returns `0` → the CALL path is used. A wrong
/// assumption therefore degrades to the existing safe behaviour, never to a
/// silently mis-tracked mirror (the risk the design doc flags).
#[cfg(windows)]
pub fn inline_rbp_tls_disp() -> usize {
    use std::sync::OnceLock;
    static DISP: OnceLock<usize> = OnceLock::new();
    *DISP.get_or_init(|| {
        if !precise_inline_frame_record_enabled() {
            return 0;
        }
        #[link(name = "kernel32")]
        extern "system" {
            fn TlsAlloc() -> u32;
            fn TlsSetValue(idx: u32, val: *mut core::ffi::c_void) -> i32;
        }
        const TLS_OUT_OF_INDEXES: u32 = 0xFFFF_FFFF;
        // TEB.TlsSlots[64] on x86-64. The probe below validates this, so an
        // incorrect constant disables inline rather than corrupting.
        const TEB_TLS_SLOTS_OFF: usize = 0x1480;
        // SAFETY: TlsAlloc/TlsSetValue are the documented Win32 TLS APIs;
        // read_gs_qword reads an 8-byte aligned TEB slot we just wrote.
        let disp = unsafe {
            'probe: {
                let slot = TlsAlloc();
                if slot == TLS_OUT_OF_INDEXES {
                    break 'probe 0;
                }
                // Non-canonical, slot-tagged sentinel (high bits set so it
                // cannot be mistaken for a real RBP or a small int in a
                // neighbour slot).
                let sentinel: usize = 0x5247_4250_4D52_0000 | (slot as usize & 0xFFFF);
                if TlsSetValue(slot, sentinel as *mut core::ffi::c_void) == 0 {
                    break 'probe 0;
                }
                let candidate = TEB_TLS_SLOTS_OFF + (slot as usize) * 8;
                if read_gs_qword(candidate) == sentinel {
                    // Reset the slot to 0 (matches the mirror's initial value);
                    // all other threads already see 0 at a fresh index.
                    TlsSetValue(slot, core::ptr::null_mut());
                    break 'probe candidate;
                }
                // Fallback: scan the static 64-slot band for the sentinel in
                // case the base constant differs on this Windows build.
                let mut d = TEB_TLS_SLOTS_OFF;
                let end = TEB_TLS_SLOTS_OFF + 64 * 8;
                while d < end {
                    if read_gs_qword(d) == sentinel {
                        TlsSetValue(slot, core::ptr::null_mut());
                        break 'probe d;
                    }
                    d += 8;
                }
                // Probe failed → leave inline disabled (CALL path).
                TlsSetValue(slot, core::ptr::null_mut());
                0
            }
        };
        // One-time visibility line, gated behind CRATONVM_DBG_INLINE_FR so the
        // (now default-on) path stays silent unless explicitly diagnosing.
        if cratonvm_types::flags::runtime_var_os("CRATONVM_DBG_INLINE_FR").is_some() {
            if disp != 0 {
                eprintln!(
                    "[INLINE-FR] inline frame-record ENABLED: storing RBP via mov gs:[{:#x}]",
                    disp
                );
            } else {
                eprintln!("[INLINE-FR] inline frame-record probe FAILED — using CALL path");
            }
        }
        disp
    })
}

#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
thread_local! {
    /// Linux counterpart of the Windows OS-TLS slot. Generated code reaches
    /// this exact Rust TLS cell as `fs:[disp32]`; the startup probe below writes
    /// a sentinel through `Cell` and reads it back through `fs:` before the
    /// displacement is accepted.
    static LINUX_INLINE_RBP_MIRROR: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
}

/// Linux x86-64 inline frame-record. ELF TLS lives at a stable signed offset
/// from the thread's FS base. Recover that offset once, encode it as the raw
/// disp32 bits expected by the x86 instruction, and sentinel-probe the exact
/// `fs:[offset]` address before enabling generated stores. Any layout or range
/// surprise returns 0 and retains the existing helper-call path.
#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
pub fn inline_rbp_tls_disp() -> usize {
    use std::sync::OnceLock;
    static DISP: OnceLock<usize> = OnceLock::new();
    *DISP.get_or_init(|| {
        if !precise_inline_frame_record_enabled() {
            return 0;
        }
        let disp = LINUX_INLINE_RBP_MIRROR.with(|cell| {
            // On the System V x86-64 ABI, fs:[0] is the thread-control-block
            // self pointer. Do not trust that convention blindly: the raw
            // sentinel read below proves the derived address before use.
            let fs_base = unsafe { read_fs_qword(0) };
            let cell_addr = cell as *const std::cell::Cell<usize> as usize;
            let delta = (cell_addr as i128) - (fs_base as i128);
            let Ok(delta32) = i32::try_from(delta) else {
                return 0;
            };
            if delta32 == 0 {
                return 0;
            }
            let old = cell.replace(0x5242_504C_494E_5558);
            let probed = unsafe { read_fs_qword(delta32 as isize) };
            cell.set(old);
            if probed == 0x5242_504C_494E_5558 {
                (delta32 as u32) as usize
            } else {
                0
            }
        });
        if cratonvm_types::flags::runtime_var_os("CRATONVM_DBG_INLINE_FR").is_some() {
            if disp != 0 {
                eprintln!(
                    "[INLINE-FR] inline frame-record ENABLED: storing RBP via mov fs:[{:#x}]",
                    disp as u32
                );
            } else {
                eprintln!("[INLINE-FR] Linux TLS probe FAILED — using CALL path");
            }
        }
        disp
    })
}

/// Unsupported targets retain the helper-call path.
#[cfg(not(any(windows, all(target_os = "linux", target_arch = "x86_64"))))]
pub fn inline_rbp_tls_disp() -> usize {
    0
}

/// Segment override used by generated inline frame-record stores.
///
/// This is shared with the OSR trampoline emitter in `lib.rs`; keeping the
/// platform byte in one place prevents that independently emitted prologue
/// from silently retaining the Windows `gs:` prefix on Linux.
pub(crate) const fn inline_rbp_tls_segment_prefix() -> u8 {
    #[cfg(windows)]
    {
        0x65
    }
    #[cfg(not(windows))]
    {
        0x64
    }
}

/// VM-side access to the Linux TLS cell used by generated `fs:` stores.
/// `None` means the startup probe did not enable the inline path.
#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
pub fn inline_rbp_tls_mirror_read() -> Option<usize> {
    if inline_rbp_tls_disp() == 0 {
        None
    } else {
        Some(LINUX_INLINE_RBP_MIRROR.with(std::cell::Cell::get))
    }
}

#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
pub fn inline_rbp_tls_mirror_write(value: usize) -> bool {
    if inline_rbp_tls_disp() == 0 {
        false
    } else {
        LINUX_INLINE_RBP_MIRROR.with(|cell| cell.set(value));
        true
    }
}

/// Read the 8-byte value at `gs:[disp]` (Windows TEB-relative). Used only by
/// the [`inline_rbp_tls_disp`] startup probe.
#[cfg(windows)]
#[inline]
unsafe fn read_gs_qword(disp: usize) -> usize {
    let val: usize;
    core::arch::asm!(
        "mov {out}, qword ptr gs:[{addr}]",
        out = out(reg) val,
        addr = in(reg) disp,
        options(nostack, preserves_flags, readonly),
    );
    val
}

/// Read the 8-byte value at `fs:[offset]` on Linux x86-64. Used only by the
/// sentinel probe for [`inline_rbp_tls_disp`].
#[cfg(all(target_os = "linux", target_arch = "x86_64"))]
#[inline]
unsafe fn read_fs_qword(offset: isize) -> usize {
    let val: usize;
    core::arch::asm!(
        "mov {out}, qword ptr fs:[{addr}]",
        out = out(reg) val,
        addr = in(reg) offset,
        options(nostack, preserves_flags, readonly),
    );
    val
}

/// Whether the JIT **shadow-stack** precise-roots codegen is enabled
/// (`CRATONVM_SHADOW_STACK`). When on, each GC-capable safepoint pushes every
/// live oop (operand-stack entries AND oop locals) onto the thread's shadow
/// stack and reloads them after the call, so a *moving* collector can rewrite
/// every JIT-held reference precisely (see `gc/src/shadow_stack.rs`). Off by
/// default → no extra codegen, byte-identical to the legacy path.
///
/// **EXPERIMENTAL — retained default-off scaffolding (precise-jit-maps-default.md
/// Step 6 decision, 2026-06-22).** This is the moving-relocation scaffolding for
/// a potential future moving/compacting young gen (`default-moving-young-gen.md`,
/// currently *design / not started*); it is **not** the correctness path (the
/// precise-maps default uses the non-moving sweep + conservative backstop) and is
/// **partial** (the moving Cheney path under-counts bt18 → 67674804). It is
/// **kept, not removed**, but must stay default-off and **must not be combined
/// with `CRATONVM_PRECISE_JIT_MAPS`** — the two interfere and reclaim. Do not
/// enable in production.
pub fn shadow_stack_maps_enabled() -> bool {
    use std::sync::OnceLock;
    static G: OnceLock<bool> = OnceLock::new();
    // `CRATONVM_MOVING_YOUNG` implies the shadow-stack codegen: the moving young
    // gen requires a COMPLETE, rewritable precise root map (see
    // `moving_young_enabled` and `collect_live_oop_homes`), so turning it on also
    // turns on the push/reload emission.
    // `CRATONVM_SHADOW_STACK` is read here, in `gc` and in `vm`, which is why
    // it lives in the shared `cratonvm_types::flags()` config rather than a
    // crate-private `getenv` cache: the emission side (this file) and the
    // root-scan side (`vm::jit::conservative_roots`, `gc::gen_heap`) MUST agree,
    // or the collector walks a shadow stack the codegen never pushed to.
    // `parse::present` == the former `var_os(..).is_some()`, so this is
    // behaviour-preserving.
    *G.get_or_init(|| cratonvm_types::flags().jit.shadow_stack || moving_young_enabled())
}

/// Whether the **default moving / compacting young generation**
/// (`CRATONVM_MOVING_YOUNG`) is enabled. Cached on first read.
///
/// When on, the JIT publishes a *complete* rewritable precise root map at every
/// GC-capable safepoint — not just the register-invisible operand oops the
/// `CRATONVM_SHADOW_STACK`-only path publishes, but EVERY live oop (operand-stack
/// entries in registers AND frame slots, and every oop local in its register or
/// canonical frame slot) — so a moving (Cheney) young collection can relocate
/// each JIT-held reference and rewrite its home in place. This completeness is
/// what lets `gen_heap::collect_garbage_inner` run the moving cycle while JIT
/// frames are live (the conservative frame scan is then suppressed — a
/// fully-precise frame needs no conservative backstop). Off by default; gated so
/// it can be validated against the bt18 = 68332206 invariant before any flip.
///
/// See `docs/feature-designs/default-moving-young-gen.md`.
///
/// **Single source of truth.** This used to `getenv` `CRATONVM_MOVING_YOUNG`
/// into a crate-private `OnceLock`, which meant the SAME gate was parsed
/// independently in three crates (`jit::x64`, `gc::gc_quiescence`,
/// `vm::jit::conservative_roots`). Codegen and the collector could therefore
/// disagree about whether the feature was on — and the two halves of this
/// feature are only sound *together*: the JIT must publish the complete
/// rewritable root map and the collector must run the moving cycle. It now
/// reads the centralized [`cratonvm_types::flags`] field, which is parsed from
/// the same variable with the same `is_some()` presence semantics, so this is
/// behaviour-preserving today and lets the default be flipped in one place
/// later. Do NOT re-introduce a local `getenv` here.
#[inline]
pub fn moving_young_enabled() -> bool {
    cratonvm_types::flags().gc.moving_young
}

fn shadow2_diag_enabled(method_label: &str) -> bool {
    if cratonvm_types::flags::runtime_var_os("CRATONVM_DBG_SHADOW2").is_none() {
        return false;
    }
    match cratonvm_types::flags::runtime_var("CRATONVM_DBG_SHADOW2_FILTER") {
        Ok(filter) if !filter.is_empty() => method_label.contains(&filter),
        _ => true,
    }
}

